tElementById(\'name\');\n            const birthdateError = document.getElementById(\'birthdate-error\');\n            const nameError = document.getElementById(\'name-error\');\n            const results = document.getElementById(\'results\');\n            const loading = document.getElementById(\'loading\');\n            const colorDisplay = document.getElementById(\'color-display\');\n            const lifePathElement = document.getElementById(\'life-path\');\n            const lifePathDescription = document.getElementById(\'life-path-description\');\n            const expressionElement = document.getElementById(\'expression\');\n            const expressionDescription = document.getElementById(\'expression-description\');\n            const colorMeaning = document.getElementById(\'color-meaning\');\n            \n            // Life path number descriptions\n            const lifePathMeanings = {\n                1: \"You are a natural leader with strong ambition and determination. Independent and original, you have great drive to accomplish your goals.\",\n                2: \"You are diplomatic and peacemaking by nature. Your strength lies in your tact, sensitivity, and ability to bring people together.\",\n                3: \"You are creative, expressive, and socially engaging. Your optimistic nature brings joy to those around you, and you have a natural talent for communication.\",\n                4: \"You are practical, steadfast, and reliable. Your methodical approach to life creates stability, and you value hard work and determination.\",\n                5: \"You are adventurous and value freedom. Your adaptable nature allows you to thrive in changing environments and experience life to its fullest.\",\n                6: \"You are nurturing, responsible, and caring. Your compassionate nature leads you to create harmony in your home and community.\",\n                7: \"You are analytical, introspective, and spiritual. Your questioning mind leads you to seek deeper understanding and wisdom.\",\n                8: \"You are ambitious, goal-oriented, and practical. Your executive abilities and good judgment position you for success in material ventures.\",\n                9: \"You are humanitarian, selfless, and compassionate. Your idealistic nature gives you a broader perspective on the human condition.\",\n                11: \"As a master number, you are highly intuitive with a spiritual awareness. You have the potential to be an inspirational teacher or leader.\",\n                22: \"As a master number, you are a practical visionary with the ability to turn dreams into reality. You can achieve great things for the benefit of humanity.\",\n                33: \"As a master number, you are a nurturing teacher with great compassion. Your selfless devotion to helping others can have a profound impact.\"\n            };\n            \n            // Expression number descriptions\n            const expressionMeanings = {\n                1: \"You express yourself with originality and strong leadership qualities. You tend to pioneer new paths rather than follow established ones.\",\n                2: \"You express yourself with diplomacy and sensitivity. Your ability to cooperate with others and attend to details makes you a valuable team member.\",\n                3: \"You express yourself with creativity and enthusiasm. Your natural charm and optimism make you an engaging communicator.\",\n                4: \"You express yourself with methodical precision and reliability. Your practical approach to problems creates solid results.\",\n                5: \"You express yourself with versatility and adaptability. Your progressive thinking and need for freedom leads to diverse experiences.\",\n                6: \"You express yourself with warmth and responsibility. Your natural ability to care for others creates harmony in relationships.\",\n                7: \"You express yourself with analytical depth and wisdom. Your thoughtful approach reveals insights others might miss.\",\n                8: \"You express yourself with authority and organization. Your executive abilities help you manage resources effectively.\",\n                9: \"You express yourself with compassion and artistic sensitivity. Your global perspective helps you see the bigger picture.\",\n                11: \"You express yourself with inspiration and spiritual insight. Your idealism can motivate others to higher awareness.\",\n                22: \"You express yourself with practical vision and powerful ambition. Your ability to implement large-scale plans sets you apart.\",\n                33: \"You express yourself with nurturing wisdom and selfless service. Your compassionate teaching abilities uplift humanity.\"\n            };\n            \n            // Numerology colors by life path number\n            const numerologyColors = {\n                1: { color: \"#FF0000\", gradient: \"linear-gradient(135deg, #ff0000, #ff5252)\", name: \"Red\", meaning: \"Red represents leadership, passion, and courage. It aligns with your independent nature and pioneering spirit, giving you the energy to overcome obstacles and forge your own path.\" },\n                2: { color: \"#FFA500\", gradient: \"linear-gradient(135deg, #ff9800, #ffb74d)\", name: \"Orange\", meaning: \"Orange represents harmony, cooperation, and balance. It enhances your natural diplomatic abilities and helps you maintain peace while working with diverse personalities.\" },\n                3: { color: \"#FFFF00\", gradient: \"linear-gradient(135deg, #ffeb3b, #fff176)\", name: \"Yellow\", meaning: \"Yellow represents creativity, joy, and self-expression. It amplifies your natural optimism and helps you communicate your ideas with enthusiasm and clarity.\" },\n                4: { color: \"#008000\", gradient: \"linear-gradient(135deg, #4caf50, #81c784)\", name: \"Green\", meaning: \"Green represents stability, growth, and practicality. It grounds your methodical approach to life and helps you build lasting foundations for success.\" },\n                5: { color: \"#0000FF\", gradient: \"linear-gradient(135deg, #2196f3, #64b5f6)\", name: \"Blue\", meaning: \"Blue represents freedom, versatility, and communication. It enhances your adaptable nature and helps you navigate life\'s constant changes with confidence.\" },\n                6: { color: \"#4B0082\", gradient: \"linear-gradient(135deg, #673ab7, #9575cd)\", name: \"Indigo\", meaning: \"Indigo represents responsibility, love, and nurturing. It aligns with your caring nature and helps you create harmony in your relationships and community.\" },\n                7: { color: \"#800080\", gradient: \"linear-gradient(135deg, #9c27b0, #ba68c8)\", name: \"Purple\", meaning: \"Purple represents wisdom, spirituality, and introspection. It deepens your analytical abilities and helps you connect with higher awareness and inner knowledge.\" },\n                8: { color: \"#A52A2A\", gradient: \"linear-gradient(135deg, #795548, #a1887f)\", name: \"Brown\", meaning: \"Brown represents ambition, organization, and material success. It supports your practical approach to achieving goals and building prosperity.\" },\n                9: { color: \"#FFC0CB\", gradient: \"linear-gradient(135deg, #e91e63, #f48fb1)\", name: \"Pink\", meaning: \"Pink represents compassion, selflessness, and universal love. It amplifies your humanitarian nature and helps you serve others with genuine care.\" },\n                11: { color: \"#FFFFFF\", gradient: \"linear-gradient(135deg, #e0e0e0, #ffffff)\", name: \"White\", meaning: \"White represents intuition, inspiration, and spiritual enlightenment. It aligns with your higher awareness and helps you illuminate paths for others.\" },\n                22: { color: \"#FFD700\", gradient: \"linear-gradient(135deg, #ffd700, #ffe57f)\", name: \"Gold\", meaning: \"Gold represents mastery, achievement, and manifestation. It supports your ability to transform ambitious visions into tangible realities.\" },\n                33: { color: \"#00FFFF\", gradient: \"linear-gradient(135deg, #00bcd4, #80deea)\", name: \"Turquoise\", meaning: \"Turquoise represents healing, teaching, and compassionate service. It enhances your nurturing wisdom and helps you uplift others through selfless guidance.\" }\n            };\n            \n            // Calculate Life Path Number\n            function calculateLifePath(birthdate) {\n                if (!birthdate) return null;\n                \n                const dateObj = new Date(birthdate);\n                const month = dateObj.getMonth() + 1;\n                const day = dateObj.getDate();\n                const year = dateObj.getFullYear();\n                \n                // Reduce month to a single digit\n                let monthNum = reduceToSingleDigit(month);\n                \n                // Reduce day to a single digit\n                let dayNum = reduceToSingleDigit(day);\n                \n                // Reduce year to a single digit\n                let yearNum = reduceToSingleDigit(year);\n                \n                // Sum the reduced values\n                let sum = monthNum + dayNum + yearNum;\n                \n                // Reduce the sum to a single digit, but preserve master numbers\n                return reduceToSingleDigit(sum, true);\n            }\n            \n            // Calculate Expression Number (from name)\n            function calculateExpression(name) {\n                if (!name) return null;\n                \n                // Remove any non-alphabetic characters\n                name = name.toUpperCase().replace(/[^A-Z]/g, \'\');\n                \n                let sum = 0;\n                \n                // Assign numeric value to each letter (A=1, B=2, etc.)\n                for (let i = 0; i < name.length; i++) {\n                    const charCode = name.charCodeAt(i) - 64; // A is ASCII 65\n                    if (charCode >= 1 && charCode <= 26) {\n                        sum += charCode;\n                    }\n                }\n                \n                // Reduce to a single digit, but preserve master numbers\n                return reduceToSingleDigit(sum, true);\n            }\n            \n            // Reduce a number to a single digit\n            function reduceToSingleDigit(num, preserveMasterNumbers = false) {\n                // Convert to string to handle each digit\n                let numStr = num.toString();\n                \n                // Keep reducing until we get a single digit or master number\n                while (numStr.length > 1) {\n                    // Check for master numbers before reducing further\n                    if (preserveMasterNumbers && (numStr === \'11\' || numStr === \'22\' || numStr === \'33\')) {\n                        return parseInt(numStr);\n                    }\n                    \n                    // Sum all digits\n                    let sum = 0;\n                    for (let i = 0; i < numStr.length; i++) {\n                        sum += parseInt(numStr[i]);\n                    }\n                    numStr = sum.toString();\n                }\n                \n                return parseInt(numStr);\n            }\n            \n            // Generate a random but harmonious secondary color\n            function getSecondaryColor(primaryColor) {\n                // Convert hex to RGB\n                const r = parseInt(primaryColor.slice(1, 3), 16);\n                const g = parseInt(primaryColor.slice(3, 5), 16);\n                const b = parseInt(primaryColor.slice(5, 7), 16);\n                \n                // Generate complementary color (sort of)\n                const r2 = Math.min(255, Math.max(0, 255 - r + Math.floor(Math.random() * 50)));\n                const g2 = Math.min(255, Math.max(0, 255 - g + Math.floor(Math.random() * 50)));\n                const b2 = Math.min(255, Math.max(0, 255 - b + Math.floor(Math.random() * 50)));\n                \n                // Convert back to hex\n                return \'#\' + \n                    r2.toString(16).padStart(2, \'0\') + \n                    g2.toString(16).padStart(2, \'0\') + \n                    b2.toString(16).padStart(2, \'0\');\n            }\n            \n            calculateBtn.addEventListener(\'click\', function() {\n                // Reset error messages\n                birthdateError.style.display = \'none\';\n                nameError.style.display = \'none\';\n                \n                // Validate inputs\n                let isValid = true;\n                \n                if (!birthdateInput.value) {\n                    birthdateError.style.display = \'block\';\n                    isValid = false;\n                }\n                \n                if (!nameInput.value) {\n                    nameError.style.display = \'block\';\n                    isValid = false;\n                }\n                \n                if (!isValid) return;\n                \n                // Show loading animation\n                loading.style.display = \'block\';\n                results.style.display = \'none\';\n                \n                // Simulate calculation delay\n                setTimeout(function() {\n                    // Calculate numerology numbers\n                    const lifePathNumber = calculateLifePath(birthdateInput.value);\n                    const expressionNumber = calculateExpression(nameInput.value);\n                    \n                    // Get the color info based on life path number\n                    const colorInfo = numerologyColors[lifePathNumber] || numerologyColors[1];\n                    \n                    // Update the color display\n                    colorDisplay.style.background = colorInfo.gradient;\n                    colorDisplay.textContent = `Your Color: \${colorInfo.name}`;\n                    \n                    // Update results\n                    lifePathElement.textContent = lifePathNumber;\n                    lifePathDescription.textContent = lifePathMeanings[lifePathNumber] || lifePathMeanings[1];\n                    \n                    expressionElement.textContent = expressionNumber;\n                    expressionDescription.textContent = expressionMeanings[expressionNumber] || expressionMeanings[1];\n                    \n                    colorMeaning.textContent = colorInfo.meaning;\n                    \n                    // Hide loading and show results\n                    loading.style.display = \'none\';\n                    results.style.display = \'block\';\n                    \n                    // Scroll to results\n                    results.scrollIntoView({ behavior: \'smooth\' });\n                }, 1500);\n            });\n        });\n    </script>\n</body>\n</html>',
